const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.user_request || typeof body.user_request !== 'string') {
  errors.push('Missing required parameter: user_request');
}

if (!body.domain || typeof body.domain !== 'object') {
  errors.push('Missing required parameter: domain');
} else {
  if (!body.domain.name) errors.push('Missing domain.name');
  if (!body.domain.description) errors.push('Missing domain.description');
}

if (!body.anthropic_api_key && !$env.ANTHROPIC_API_KEY) {
  errors.push('Missing anthropic_api_key');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    user_request: body.user_request.trim(),
    domain: body.domain,
    user_id: body.user_id || null,
    guild_id: body.guild_id || null,
    anthropic_api_key: body.anthropic_api_key || $env.ANTHROPIC_API_KEY,
    model: body.model || 'claude-haiku-4-5-20251001'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Default user_state for fail-open scenarios
const defaultUserState = {
  emotions: ["neutral"],
  urgency: "low",
  constraints: {
    time: null,
    budget: null,
    ingredients: null,
    equipment: null,
    diet: null,
    servings: null
  },
  user_level: "unknown",
  tone_preference: "neutral"
};

try {
  // Handle API error - fail-open with default state
  if (input.error) {
    return [{
      json: {
        is_valid: true,
        issue_type: null,
        response: null,
        user_state: defaultUserState,
        _error: input.error.message
      }
    }];
  }

  // Extract text content from Claude response
  let textContent = '';
  for (const block of (input.content || [])) {
    if (block.type === 'text') {
      textContent += block.text;
    }
  }

  // Parse JSON from response
  let result;
  try {
    const cleaned = textContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    result = JSON.parse(cleaned);
  } catch (e) {
    // If parsing fails, assume valid request with default state (fail-open)
    return [{
      json: {
        is_valid: true,
        issue_type: null,
        response: null,
        user_state: defaultUserState,
        _parse_error: e.message
      }
    }];
  }

  // Validate and normalize user_state
  const userState = result.user_state || {};
  const normalizedUserState = {
    emotions: Array.isArray(userState.emotions) ? userState.emotions : ["neutral"],
    urgency: ["low", "medium", "high"].includes(userState.urgency) ? userState.urgency : "low",
    constraints: {
      time: userState.constraints?.time || null,
      budget: userState.constraints?.budget || null,
      ingredients: userState.constraints?.ingredients || null,
      equipment: userState.constraints?.equipment || null,
      diet: userState.constraints?.diet || null,
      servings: userState.constraints?.servings || null
    },
    user_level: ["beginner", "intermediate", "advanced", "unknown"].includes(userState.user_level) 
      ? userState.user_level : "unknown",
    tone_preference: ["reassuring", "direct", "enthusiastic", "pedagogical", "neutral"].includes(userState.tone_preference)
      ? userState.tone_preference : "neutral"
  };

  // Return RFC-044 compliant format
  return [{
    json: {
      is_valid: result.is_valid ?? true,
      issue_type: result.issue_type || null,
      response: result.response || null,
      user_state: normalizedUserState
    }
  }];
} catch (e) {
  // Fail-open: accept request with default state if error
  return [{
    json: {
      is_valid: true,
      issue_type: null,
      response: null,
      user_state: defaultUserState,
      _error: e.message
    }
  }];
}
